{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build list of mutual reachability edges
    edges = []
    for u, v, d in distances:
        # canonicalize: store smaller first
        if u > v:
            u, v = v, u
        w = max(core_dist[u], core_dist[v], d)
        edges.append((w, u, v))

    # Sort by weight, then first node, then second node (all ascending)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    needed = len(nodes) - 1
    count = 0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            count += 1
            if count == needed:
                break

    if count != needed:
        raise ValueError('Graph is not connected; no spanning tree exists')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
